334:   inline std::istream& readAt(
335:     std::istream& stream, std::streampos pos,
336:     std::byte* buffer, std::size_t size) {
337:     if (!stream) {
338:       throw std::runtime_error("Stream is not valid for reading");
339:     }
340:     struct SeekGuard {
341:       std::istream& stream;
342:       std::streampos oldPos;
343:       SeekGuard(std::istream& s, std::streampos p) : stream(s), oldPos(s.tellg()) {
344:         stream.seekg(p);
345:       }
346:       ~SeekGuard() {
347:         stream.seekg(oldPos);
348:       }
349:     } seekGuard(stream, pos);
350:     if (!stream) {
351:       throw std::runtime_error("Failed to seek to position in stream");
352:     }
353:     stream.read(reinterpret_cast<char*>(buffer), size);
354:     if (!stream || static_cast<std::size_t>(stream.gcount()) != size) {
355:       throw std::runtime_error("Failed to read the requested number of bytes from the stream");
356:     }
357:     return stream;
358:   }
359: 
360:   template <typename T>
361:   std::ostream& writeValue(std::ostream& stream, T value, bool mustSwap = false) {
362:     if (!stream) {
363:       throw std::runtime_error("Stream is not valid for writing");
364:     }
365:     if (mustSwap) {
366:       value = swap(value);
367:     }
368:     stream.write(reinterpret_cast<const char*>(&value), sizeof(value));
369:     return stream;
370:   }
371: 
372:   inline std::ostream& writeAt(
373:     std::ostream& stream, std::streampos pos,
374:     const std::byte* buffer, std::size_t size) {
375:     if (!stream) {
376:       throw std::runtime_error("Stream is not valid for writing");
377:     }
378:     struct SeekGuard {
379:       std::ostream& stream;
380:       std::streampos oldPos;
381:       SeekGuard(std::ostream& s, std::streampos p) : stream(s), oldPos(s.tellp()) {
382:         // try to seek to the specified position
383:         stream.seekp(p);
384:         if (stream.fail()) {
385:           // if seeking fails, we check if we tried to seek beyond the end of
386:           // the stream and if so, we pad the stream with zeros until we reach
387:           // the desired position
388:           stream.clear(); // Clear any error flags
389:           stream.seekp(0, std::ios_base::end);
390:           while (stream && stream.tellp() < p) {
391:             stream.put(0); // Pad with zeros if necessary
392:           }
393:           assert(stream.tellp() == p && "SeekGuard did not reach the desired position");
394:         }
395:       }
396:       ~SeekGuard() {
397:         stream.seekp(oldPos);
398:       }
399:     } seekGuard(stream, pos);
400:     if (!stream || stream.tellp() != pos) {
401:       throw std::runtime_error("Failed to seek to position in stream");
402:     }
403:     stream.write(reinterpret_cast<const char*>(buffer), size);
404:     return stream;
405:   }
