632:     using ImageData = std::vector<std::vector<std::byte>>;
633: 
634:     const Header& header() const { return header_; }
635:     const std::vector<IFD>& ifds() const { return ifds_; }
636: 
637:     std::istream& stream() const {
638:       if (!stream_) {
639:         throw std::runtime_error("Stream is not set for this TIFF image");
640:       }
641:       return *stream_;
642:     }
