712:     static ImageData readImageTiles(std::istream& stream, const IFD& ifd) {
713:       const auto& entries = ifd.entries();
714:       std::vector<uint32_t> tileOffsets, tileByteCounts;
715:       { //copy offsets
716:         const auto& entry = ifd.getEntry(Tag::TileOffsets, "TileOffsets entry not found in IFD");
717:         copyVector<uint32_t>(entry.type(), entry.values(), entry.count(), tileOffsets);
718:       }
719:       { //copy byte counts
720:         const auto& entry = ifd.getEntry(Tag::TileByteCounts, "TileByteCounts entry not found in IFD");
721:         copyVector<uint32_t>(entry.type(), entry.values(), entry.count(), tileByteCounts);
722:       }
723:       if (tileOffsets.size() != tileByteCounts.size()) {
724:         throw std::runtime_error("Mismatch between number of TileOffsets and TileByteCounts");
725:       }
726:       ImageData imageData;
727:       for (size_t i = 0; i < tileOffsets.size(); ++i) {
728:         const uint32_t offset = tileOffsets[i];
729:         const uint32_t byteCount = tileByteCounts[i];
730:         if (offset < 8 || byteCount == 0) {
731:           throw std::runtime_error("Invalid tile offset or byte count");
732:         }
733:         imageData.emplace_back(byteCount);
734:         readAt(stream, offset, imageData.back().data(), byteCount);
735:       }
736:       return imageData;
737:     }
738: 
739:     private:
740:       Header header_;
741:       std::vector<IFD> ifds_; // List of IFDs in the TIFF image
742:       std::unique_ptr<std::istream> stream_;
743:   };
744: 
745:   struct LoadParams {
746:     std::optional<uint16_t> ifdIndex; // Optional IFD index to load
747:   };
748: 
749:   using LoadCallback = std::function<void(
750:     const TiffImage::Header&, const TiffImage::IFD&, TiffImage::ImageData)>;
751: 
752:   inline void load(std::istream& stream, LoadCallback&& callback, const LoadParams& params = {}) {
753:     // Read the TIFF image from the stream
754:     TiffImage image = TiffImage::read(stream);
755:     const auto& header = image.header();
756: 
757:     if (params.ifdIndex && params.ifdIndex.value() >= image.ifds().size()) {
758:       throw std::runtime_error("Requested IFD index is out of bounds");
759:     }
760: 
761:     for (size_t i = 0; i < image.ifds().size(); ++i) {
762:       if (!params.ifdIndex || params.ifdIndex.value() == i) {
763:         // If a specific IFD index is requested, only process that IFD
764:         // Otherwise, process all IFDs
765:         const auto& ifd = image.ifds()[i];
766:         if (ifd.entries().contains(Tag::StripOffsets)) {
767:           // image contains strip offsets
768:           callback(header, ifd, TiffImage::readImageStrips(stream, ifd));
769:         } else if (ifd.entries().contains(Tag::TileByteCounts)) {
770:           // image contains tile byte counts
771:           callback(header, ifd, TiffImage::readImageTiles(stream, ifd));
772:         } else {
773:           throw std::runtime_error("Unsupported IFD format");
774:         }
775:       }
776:     }
777:   }
778: 
779:   inline void load(const std::string& filename, LoadCallback&& callback, const LoadParams& params = {}) {
780:     std::ifstream file(filename, std::ios::binary);
781:     if (!file) {
782:       throw std::runtime_error("Failed to open TIFF file: " + std::string(filename));
783:     }
784:     load(file, std::move(callback), params);
785:   }
